pub(crate) fn own_hook_installed(label: &'static str, replacement: *const ()) {
    let replacement = replacement as usize;
    if replacement == 0 || !native_seams::OWN_HOOK_PAIRS.iter().any(|(_, hook)| *hook == label) {
        return;
