            Some(Ok(result)) => Some((s.inflight.take().unwrap(), result)),
            Some(Err(mpsc::TryRecvError::Disconnected)) => Some((
                s.inflight.take().unwrap(),
                Err("Mii import writer disconnected".into()),
            )),
            _ => None,
        }
