            mii_ordinary_player::refresh_library(&library);
            mii_ordinary_cpu::refresh_library(&library);
            inflight.configuration
        });
        let result = if current(&inflight.job) {
            result
        } else {
            Err("Replay selection retired".into())
        };
        finish(inflight.job, result);
    }
