    if s.inflight.is_some() {
        return;
    }
    while s.pending.front().is_some_and(|job| !current(job)) {
        finish(
            s.pending.pop_front().unwrap(),
            Err("Replay selection retired".into()),
        );
    }
    if s.pending.is_empty() {
        WORK.store(false, Ordering::Release);
        return;
    }
